import{z as n,x as B,o as t,c as p,q as s,j as l,D as E,d as r,s as i,S as o,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"Hyper-NA 之后的物理极限","description":"","frontmatter":{"title":"Hyper-NA 之后的物理极限","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/post-hyper-na-limits.md","filePath":"litho/post-hyper-na-limits.md","lastUpdated":1791063341000}'),D={name:"litho/post-hyper-na-limits.md"};function d(m,a,h,N,u,_){const A=B("Mermaid");return t(),p("div",null,[a[2]||(a[2]=s('<h1 id="hyper-na-之后的物理极限" tabindex="-1">Hyper-NA 之后的物理极限 <a class="header-anchor" href="#hyper-na-之后的物理极限" aria-label="Permalink to &quot;Hyper-NA 之后的物理极限&quot;">​</a></h1><div class="epigraph"><p>再抬 NA 会继续削焦深、加厚掩模 3D 阴影、逼更薄胶；再缩波长碰到镜面、源与随机。极限是一张预算表的同时崩，不是单一瑞利等式的终点。</p><footer>—— 对照 High-NA/Hyper-NA 讨论中的 DOF、mask 3D、随机与 6.x nm 设想；不重推分辨率公式</footer></div><p><a href="/litho/fel-euv-source">上一课</a>说明源替代也不免费。缺口是投影光学这条主路的尽头怎么讲。本课钉 Hyper-NA 之后的物理极限，结束替代课序与本批课程。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>0.55 NA 已把半场、薄胶、anamorphic 掩模写进合同。再往上（公开讨论过的更高 NA）会：DOF 更薄（形貌课的台阶更致命）、入射角更大（掩模 3D 与吸收体阴影更毒）、胶更薄（选择比与随机更紧）、扫描机更大更贵。6.x nm（BEUV）设想改多层周期与源，材料与随机不会自动变好。3D 器件与键合把密度轴转到垂直，可能比再挤平面 k1 更经济——摩尔课的分母可以靠堆叠。</p><p><span class="marginnote">数字实例：粗略用 \\(k_2\\lambda/\\mathrm{NA}^2\\) 估焦深，EUV 0.33 NA 约为 31 nm 量级；0.55 NA 只剩约 11 nm——NA 抬了不到一倍，允许的台阶与胶厚直接砍去三分之二，这就是「同时崩」的算术来源。</span></p><p>缺口是<strong>多约束同时收紧</strong>，不是再写一次 \\(k_1λ/\\mathrm{NA}\\)。主干已教 DOF、随机、mask 3D；本课只把它们放到「再往下一代」的交点上。</p><h3 id="不把极限当停工指令" tabindex="-1">不把极限当停工指令 <a class="header-anchor" href="#不把极限当停工指令" aria-label="Permalink to &quot;不把极限当停工指令&quot;">​</a></h3><p>物理墙移动成本函数，DTCO 可以选择停在某平面节距、改助推器、改 3D。极限课防止的是幻想「总会有下一档 NA」。</p><p><span class="marginnote">IRDS 红格与本课同构：没有已知解的格子，不是禁止研究，是禁止把格子当已交付。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>列预算：DOF vs 形貌、光子预算 vs 随机、掩模 3D vs 吸收体、资本 vs 交叉。任何新提案（更高 NA、BEUV、FEL、直写）必须同时过这张表。与良率：随机 p 与 \\(A_c\\) 在更密节距上抬分母风险。</p>',12)),(t(),l(o,null,{default:E(()=>[i(A,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E6%96%B0%E6%8F%90%E6%A1%88%20%E6%9B%B4%E9%AB%98NA%20%2F%20BEUV%20%2F%20%E7%9B%B4%E5%86%99%22%5D%20--%3E%20C1%7B%22DOF%20vs%20%E5%BD%A2%E8%B2%8C%22%7D%0A%20%20P%20--%3E%20C2%7B%22%E5%85%89%E5%AD%90%20vs%20%E9%9A%8F%E6%9C%BA%22%7D%0A%20%20P%20--%3E%20C3%7B%22%E6%8E%A9%E6%A8%A1%203D%20vs%20%E5%90%B8%E6%94%B6%E4%BD%93%22%7D%0A%20%20P%20--%3E%20C4%7B%22%E8%B5%84%E6%9C%AC%20vs%20%E4%BA%A4%E5%8F%89%22%7D%0A%20%20C1%20--%3E%20S%7B%22%E5%85%A8%E7%BB%BF%3F%22%7D%0A%20%20C2%20--%3E%20S%0A%20%20C3%20--%3E%20S%0A%20%20C4%20--%3E%20S%0A%20%20S%20--%20%22%E6%98%AF%22%20--%3E%20OK%5B%22%E4%B8%8B%E4%B8%80%E4%BB%A3%E5%80%99%E9%80%89%22%5D%0A%20%20S%20--%20%22%E5%90%A6%22%20--%3E%20NO%5B%22%E5%87%BA%E5%B1%80%E6%88%96%E5%8A%A0%E5%8A%A9%E6%8E%A8%E5%99%A8%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[e("span",{class:"marginnote"},"「必须同时过这张表」这一步如果跳过，后面就会重演历史：单看分辨率，每个新波长、新 NA 都显得「可行」；等焦深、随机和掩模账一起爆，钱已经花在光源与镜头上。这张表是给投资与路线决策用的，不是装饰。")],-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"成像系统把频率通带再打开一截，必然在 z 方向、角度方向、光子计数上付钱。这是傅里叶变换与泊松统计，不是某公司不愿意。垂直集成改变的是要印的平面节距需求，从而绕过而不是打破通带。",-1)),(t(),l(o,null,{default:E(()=>[i(A,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20NA%5B%22%E6%9B%B4%E9%AB%98%20NA%22%5D%20--%3E%20DOF%5B%22%E7%84%A6%E6%B7%B1%E5%B4%A9%E6%BA%83%22%5D%0A%20%20NA%20--%3E%20M3D%5B%22%E6%8E%A9%E6%A8%A1%203D%20%2F%20%E9%98%B4%E5%BD%B1%22%5D%0A%20%20NA%20--%3E%20THIN%5B%22%E6%9B%B4%E8%96%84%E8%83%B6%20%2F%20%E9%9A%8F%E6%9C%BA%22%5D%0A%20%20WL%5B%22%E6%9B%B4%E7%9F%AD%20%CE%BB%22%5D%20--%3E%20MAT%5B%22%E9%95%9C%20%2F%20%E6%BA%90%20%2F%20%E8%83%B6%E6%9D%90%E6%96%99%22%5D%0A%20%20STACK%5B%223D%20%E5%A0%86%E5%8F%A0%22%5D%20--%3E%20BYPASS%5B%22%E9%99%8D%E4%BD%8E%E5%B9%B3%E9%9D%A2%E8%8A%82%E8%B7%9D%E5%8E%8B%E5%8A%9B%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=s('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不预言停在哪一代。不发明 6.x nm 量产时间。本课结束路线图门，不重开掩模制造。</p><p><span class="marginnote">直觉类比：成像通带像一条只有两车道的隧道。3D 堆叠不是把隧道凿宽，而是少派几辆车过——把本来要印在平面的互连搬进垂直方向，平面节距需求变小，墙还在原地，却不挡路了。</span></p><p>后课若在附录：论文与型号对照这些墙，不插入主干。读者默认：平面光刻的下一档永远是多约束交，不是单参数。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Hyper-NA 之后同时碰到 DOF、mask 3D、薄胶随机与资本。</li><li>更短波长另开材料与源墙。</li><li>3D 堆叠可绕过而非打破平面通带。</li><li>新提案必须过整张预算表。</li><li>出处：High-NA 公开约束讨论；IRDS 需求红格定位；随机与 mask 3D 主干课的汇合。</li></ul>',6))])}const C=n(D,[["render",d]]);export{f as __pageData,C as default};
